//! Reference service_auth ceremony. No assertion is issued before authenticated confirmation.
use crate::Error;
use rand_core::{OsRng, RngCore};

pub struct PendingClaim {
    code: String,
    expires_at: i64,
    attempts: u8,
    subject: Option<String>,
    consumed: bool,
}
impl PendingClaim {
    /// The host must bind this object to an unguessable claim_token and rate-limit creation/polling.
    pub fn new(now: i64) -> Result<(Self, String), Error> {
        if !(0..=i64::MAX - 600).contains(&now) {
            return Err(Error::Claim);
        }
        // Rejection sampling avoids modulo bias.
        let sample = loop {
            let n = OsRng.next_u32();
            if n < u32::MAX - u32::MAX % 1_000_000 {
                break n;
            }
        };
        let code = format!("{:06}", sample % 1_000_000);
        Ok((
            Self {
                code: code.clone(),
                expires_at: now + 600,
                attempts: 0,
                subject: None,
                consumed: false,
            },
            code,
        ))
    }
    /// authenticated_subject MUST come from the host session, never the agent's request body.
    pub fn confirm(
        &mut self,
        code: &str,
        authenticated_subject: &str,
        now: i64,
    ) -> Result<(), Error> {
        if now < 0
            || now >= self.expires_at
            || self.attempts >= 5
            || self.subject.is_some()
            || self.consumed
            || authenticated_subject.is_empty()
        {
            return Err(Error::Claim);
        }
        self.attempts += 1;
        if code != self.code {
            return Err(Error::Claim);
        }
        self.subject = Some(authenticated_subject.into());
        Ok(())
    }
    /// Consume once; the host can now mint a service identity_assertion for this subject.
    pub fn take_subject(&mut self, now: i64) -> Result<String, Error> {
        if now < 0 || now >= self.expires_at || self.consumed {
            return Err(Error::Claim);
        }
        let subject = self.subject.clone().ok_or(Error::Claim)?;
        self.consumed = true;
        Ok(subject)
    }
}

//! Local auth.md building blocks. Trust roots and authenticated user sessions are host inputs.
//! This crate does not fetch keys or infer trust from a DID or Markdown document.
#[cfg(feature = "host")]
pub mod claims;
pub mod protocol;
#[cfg(feature = "host")]
pub mod service;
pub mod token;

use arkhe_core::{
    worker::{CognitiveOperation, WorkerExecutionRecord},
    Digest32,
};

#[derive(Debug, thiserror::Error, PartialEq, Eq)]
pub enum Error {
    #[error("invalid token or signature")]
    InvalidToken,
    #[error("untrusted issuer, audience, client or key")]
    Untrusted,
    #[error("expired or invalid time window")]
    Expired,
    #[error("replayed assertion")]
    Replay,
    #[error("revoked credential or registration")]
    Revoked,
    #[error("insufficient scope")]
    Scope,
    #[error("claim pending, expired, locked or already consumed")]
    Claim,
    #[error("invalid discovery configuration")]
    Discovery,
}

/// Candidate only: a host must sign and admit this through its WorkerVerifier/kernel.
/// Credentials never enter the record; only a domain-separated token digest does.
pub fn registration_record(
    request: Digest32,
    token: &token::VerifiedToken,
    execution_id: String,
) -> Result<WorkerExecutionRecord, Error> {
    if !token.is_access() {
        return Err(Error::InvalidToken);
    }
    Ok(WorkerExecutionRecord {
        classification: None,
        operation: Some(CognitiveOperation::Execute),
        module_id: "auth-md-registration-v1".into(),
        module_version: env!("CARGO_PKG_VERSION").into(),
        input_digest: request,
        output_digest: token.digest(),
        evidence_refs: vec![],
        confidence_bps: None,
        uncertainty_note: None,
        execution_id,
    })
}

//! Structured discovery is authoritative; Markdown is never parsed as executable policy.
use crate::Error;
use serde::{Deserialize, Serialize};

#[derive(Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Discovery {
    pub resource: String,
    pub issuer: String,
    pub scopes_supported: Vec<String>,
}
impl Discovery {
    pub fn validate(&self) -> Result<(), Error> {
        // This local profile uses HTTPS origins only, preventing injected paths/headers in templates.
        let origin = |s: &str| {
            s.strip_prefix("https://").is_some_and(|host| {
                !host.is_empty()
                    && host.contains('.')
                    && host
                        .bytes()
                        .all(|b| b.is_ascii_alphanumeric() || b == b'.' || b == b'-')
            })
        };
        if !origin(&self.resource)
            || !origin(&self.issuer)
            || self.scopes_supported.is_empty()
            || self.scopes_supported.iter().any(|s| {
                s.is_empty()
                    || !s
                        .bytes()
                        .all(|b| b.is_ascii_alphanumeric() || b"_:.-".contains(&b))
            })
        {
            return Err(Error::Discovery);
        }
        Ok(())
    }
    pub fn protected_resource(&self) -> Result<serde_json::Value, Error> {
        self.validate()?;
        Ok(
            serde_json::json!({"resource": self.resource, "authorization_servers": [self.issuer], "scopes_supported": self.scopes_supported, "bearer_methods_supported": ["header"]}),
        )
    }
    /// Local metadata describes library capabilities, not a deployed or certified OAuth server.
    pub fn auth_md(&self) -> Result<String, Error> {
        self.validate()?;
        Ok(format!("# auth.md\n\nArkhe Orkut integration candidate.\n\n## 1. Discover\n\nRead {}/.well-known/oauth-protected-resource. Structured metadata is authoritative.\n\n## 2. Register\n\nThe host must deploy /agent/identity, /oauth2/token, /oauth2/revoke and authenticated claim confirmation before advertising supported flows. Provider assertions require a pinned issuer, key, audience and client plus fresh verified identity. Service assertions are exchanged separately for access tokens.\n\n## 3. Scopes\n\n{}\n\n## 4. Claims and revocation\n\nConfirm a claim only in an authenticated host session. Registration revocation invalidates its assertions and derived credentials.\n", self.resource, self.scopes_supported.join(", ")))
    }
}
